-- 创建自定义类型
CREATE TYPE address AS (
    street text,
    city text,
    zipcode varchar(10)
);

-- 在表中使用
CREATE TABLE customers (
    id serial PRIMARY KEY,
    name text,
    home_address address,  -- 直接使用自定义类型
    shipping_addresses address[]  -- 地址数组
);

-- 父表
CREATE TABLE vehicles (
    id serial PRIMARY KEY,
    name text,
    max_speed integer
);

-- 子表继承
CREATE TABLE cars (
    fuel_type text
) INHERITS (vehicles);

CREATE TABLE trucks (
    load_capacity integer
) INHERITS (vehicles);

-- 查询会包含所有子表数据
SELECT * FROM vehicles;

-- 主表，存储公共属性和类型
CREATE TABLE entities (
    id SERIAL PRIMARY KEY,
    type VARCHAR(20) NOT NULL, -- 'USER', 'ADMIN', 'GUEST'
    created_at TIMESTAMP DEFAULT NOW()
);
-- 详情表，存储特有属性，通过外键关联
CREATE TABLE user_details (
    entity_id INT PRIMARY KEY REFERENCES entities(id),
    email VARCHAR(100) UNIQUE,
    phone VARCHAR(20)
);
CREATE TABLE admin_details (
    entity_id INT PRIMARY KEY REFERENCES entities(id),
    department VARCHAR(50),
    permission_level INT
);

CREATE TABLE products (
    id SERIAL PRIMARY KEY,
    name TEXT,
    type VARCHAR(20) NOT NULL,
    attributes JSONB, -- 存储不同类型的特有属性
    CONSTRAINT valid_attributes CHECK (
        (type = 'book' AND attributes ? 'isbn') OR
        (type = 'clothing' AND attributes ? 'size')
    )
);

-- 自定义复数类型
CREATE TYPE complex AS (r float8, i float8);

-- 自定义加法操作符
CREATE FUNCTION complex_add(complex, complex)
RETURNS complex AS $$
    SELECT ($1.r + $2.r, $1.i + $2.i)::complex;
$$ LANGUAGE SQL;

CREATE OPERATOR + (
    leftarg = complex,
    rightarg = complex,
    procedure = complex_add
);

-- 使用自定义操作符
SELECT (1.0,1.0)::complex + (2.0,3.0)::complex;

-- 存储整个JSON文档(JSONB类型)
CREATE TABLE products (
    id serial PRIMARY KEY,
    attributes jsonb  -- 支持索引和深度查询
);

-- 查询JSON内部字段
SELECT attributes->>'color' FROM products 
WHERE attributes @> '{"category":"electronics"}';

-- 查看表的最后一次 autovacuum 和 analyze 时间
SELECT relname, last_autovacuum, last_autoanalyze
FROM pg_stat_user_tables
ORDER BY last_autovacuum DESC NULLS LAST;


-- 观察当前有哪些 autovacuum 正在运行
SELECT * FROM pg_stat_activity WHERE query LIKE '%autovacuum%';

JSONB 列可以存储 JSON 标准支持的所有数据类型：字符串、数字、布尔值、null、对象（字典）和数组。这些类型可以任意嵌套。

CREATE TABLE user_profiles (
    id SERIAL PRIMARY KEY,
    name TEXT,
    preferences JSONB -- 用户偏好设置
);

INSERT INTO user_profiles (name, preferences) VALUES
('Alice', '{"theme": "dark", "notifications": {"email": true, "sms": false}, "tags": ["admin", "editor"]}'::jsonb),
('Bob', '{"theme": "light", "settings": {"language": "zh-CN", "timezone": "Asia/Shanghai"}}'::jsonb);

-- 为 preferences 列创建默认的 GIN 索引（支持 @>, ?, ?|, ?& 操作符）
CREATE INDEX idx_user_profiles_preferences ON user_profiles USING GIN (preferences);

-- 创建更精细的 JSON 路径表达式索引
CREATE INDEX idx_user_profiles_theme ON user_preferences USING GIN ((preferences->'theme'));

-- 创建一个 JSONB 对象
SELECT jsonb_build_object('name', 'Alice', 'age', 30);

-- 将多行结果聚合为一个 JSONB 数组
SELECT jsonb_agg(name) FROM user_profiles;

-- 修改 JSONB 数据（PostgreSQL 14+ 支持 jsonb_set）
UPDATE user_profiles 
SET preferences = jsonb_set(preferences, '{theme}', '"light"')
WHERE name = 'Alice';

DO $$
DECLARE
    batch_size INT := 5000;
    total INT := (SELECT count(*) FROM large_table WHERE condition);
    batches INT := ceiling(total::float/batch_size);
BEGIN
    FOR i IN 0..batches-1 LOOP
        RAISE NOTICE 'Processing batch % of %', i+1, batches;

        UPDATE large_table 
        SET column = new_value
        WHERE id IN (
            SELECT id 
            FROM large_table 
            WHERE condition
            ORDER BY id
            LIMIT batch_size OFFSET (i*batch_size)
        );

        COMMIT;
    END LOOP;
END $$;

表创建:
CREATE TABLE measurement (
    id bigserial,
    log_time timestamp,
    data jsonb
) PARTITION BY RANGE (log_time);

子分区创建:
-- 历史分区（每月）
CREATE TABLE measurement_202301 PARTITION OF measurement
    FOR VALUES FROM ('2023-01-01') TO ('2023-02-01');

-- 当前分区（按周）
CREATE TABLE measurement_current PARTITION OF measurement
    FOR VALUES FROM ('2023-06-01') TO ('2023-06-08');

索引策略:
-- 全局索引（跨分区）
CREATE INDEX idx_measurement_id ON measurement (id);

-- 本地索引（每个分区独立）
CREATE INDEX idx_measurement_logtime ON measurement (log_time);

系统总内存为 32GB 的情况下:
shared_buffers = 8GB; 
postgresql 的主要内存缓冲区池，用于缓存表数据、索引页，减少对磁盘的读取；
默认值为 128MB;  通常建议为系统内存的 25%;
该设置对大数据量表:  有更多表页和索引页可以驻留在内存；减少物理 IO; 提高 select 性能(尤其是频繁访问的热数据)

effective_cache_size = 24GB
postgresql 的优化器参考值: 告诉它操作系统层面能缓存多少页(包括 OS 缓存)；这个值不会占用内存，只是个估算值，影响查询计划生成;
默认值为 4GB; 通常建议为系统内存的 60%~75%;
该设置对大数据量表: 优化器会认为更多数据可以被缓存，从而更倾向于使用索引(index scan) 而不是顺序扫描(seq scan)

work_mem = 64MB
每个排序操作, hash join, 聚合阶段能用额内存
默认值为 4MB 或 8MB;
但如果有 100 个并发连接，每个用 64MB, 瞬间就会用到 6.4GB;
可以综合实际情况考虑；

maintenance_work_mem = 2GB
用于执行后台维护任务的内存, 如: 
vacuum; create index; alter table; analyze
默认值为 64MB;  通常设置为 1~4GB, 对大表尤其重要；
该设置对大数据量表: vacuum 和 create index 可以用更多的内存构建中间结构; 减少磁盘临时文件写入; 极大加快维护任务的速度(尤其是 autovacuum)

